const body = $json.body ?? $json;
const ingredients = Array.isArray(body.ingredients) ? body.ingredients : [];
const preferences = body.preferences ?? {};

if (ingredients.length === 0) {
  throw new Error('Missing ingredients array in request payload');
}

const normalizedPreferences = {
  portions: Number(preferences.portions ?? 1),
  cooks: Number(preferences.cooks ?? 1),
  cookingTime: String(preferences.cookingTime ?? 'medium'),
  cuisine: String(preferences.cuisine ?? 'fusion'),
  diets: Array.isArray(preferences.diets) ? preferences.diets : ['none'],
};

const ingredientSummary = ingredients
  .map((item) => `${item.quantity} ${item.unit} ${item.name}`.trim())
  .join(', ');

const prompt = `You are a culinary AI planner. Create exactly 3 recipe suggestions based on the provided data.

Ingredients: ${ingredientSummary}
Portions: ${normalizedPreferences.portions}
People cooking: ${normalizedPreferences.cooks}
Cooking time preference: ${normalizedPreferences.cookingTime}
Cuisine preference: ${normalizedPreferences.cuisine}
Diet preferences: ${normalizedPreferences.diets.join(', ')}

Output strict JSON with this schema:
{
  "recipes": [
    {
      "title": "string",
      "description": "string",
      "estimatedMinutes": number,
      "ingredients": ["string"],
      "steps": ["string"]
    }
  ]
}`;

return [{
  json: {
    ingredients,
    preferences: normalizedPreferences,
    prompt,
  },
}];

