const body = $json.body ?? $json;

let ip = String(body.clientIp || '').trim();

if (!ip || ip === '127.0.0.1') {
  try {
    const ipResponse = await fetch('https://api.ipify.org?format=json');
    if (ipResponse.ok) {
      const ipData = await ipResponse.json();
      ip = ipData.ip || '127.0.0.1';
    }
  } catch (error) {
    ip = '127.0.0.1';
  }
}

const ipSlug = ip.replace(/[^a-zA-Z0-9]/g, '-').replace(/^-+|-+$/g, '') || 'localhost';
const today = new Date().toISOString().slice(0, 10);
const dbUrl = 'https://code-a-cuisine-ccf1f-default-rtdb.firebaseio.com';
const perIpPath = `${dbUrl}/quota/${today}/ips/${ipSlug}.json`;
const globalPath = `${dbUrl}/quota/${today}/global.json`;
const perIpLimit = 3;
const globalLimit = 12;

const readCounter = async (path) => {
  try {
    const response = await fetch(path);
    if (!response.ok) {
      return 0;
    }

    const value = await response.json();
    if (typeof value === 'number' && Number.isFinite(value)) {
      return Math.max(0, value);
    }

    if (value && typeof value === 'object') {
      const possibleCount = value.count ?? value.used ?? value.perIpUsed ?? value.globalUsed;
      if (typeof possibleCount === 'number' && Number.isFinite(possibleCount)) {
        return Math.max(0, possibleCount);
      }
    }
  } catch (error) {
    console.log(`Quota read failed for ${path}: ${error.message}`);
  }

  return 0;
};

const perIpUsed = await readCounter(perIpPath);
const globalUsed = await readCounter(globalPath);
const quota = {
  date: today,
  ipAddress: ip,
  ipVersion: 'unknown',
  perIpLimit,
  perIpUsed,
  perIpRemaining: Math.max(0, perIpLimit - perIpUsed),
  globalLimit,
  globalUsed,
  globalRemaining: Math.max(0, globalLimit - globalUsed),
};

const quotaOk = quota.perIpRemaining > 0 && quota.globalRemaining > 0;
let quotaExceededMessage = null;

if (!quotaOk) {
  quotaExceededMessage = quota.perIpRemaining <= 0
    ? `Daily generation limit reached. You can generate up to ${perIpLimit} recipes per day from this IP address.`
    : `System-wide daily generation limit reached. Up to ${globalLimit} recipes can be generated across the app per day.`;
} else {
  const nextPerIpUsed = perIpUsed + 1;
  const nextGlobalUsed = globalUsed + 1;

  try {
    await Promise.all([
      fetch(perIpPath, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nextPerIpUsed),
      }),
      fetch(globalPath, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nextGlobalUsed),
      }),
    ]);

    quota.perIpUsed = nextPerIpUsed;
    quota.perIpRemaining = Math.max(0, perIpLimit - nextPerIpUsed);
    quota.globalUsed = nextGlobalUsed;
    quota.globalRemaining = Math.max(0, globalLimit - nextGlobalUsed);
  } catch (error) {
    console.log(`Quota update failed: ${error.message}`);
  }
}

return [{
  json: {
    ...$json,
    ipAddress: ip,
    ipSlug,
    quotaDate: today,
    quotaOk,
    quota,
    quotaExceededMessage,
  }
}];

