  globalUsed,
  globalRemaining: Math.max(0, globalLimit - globalUsed),
};

let message = null;
if (quota.perIpRemaining <= 0) {
  message = `Daily generation limit reached. You can generate up to ${perIpLimit} recipes per day from this IP address.`;
} else if (quota.globalRemaining <= 0) {
  message = `System-wide daily generation limit reached. Up to ${globalLimit} recipes can be generated across the app per day.`;
}

return [{
  json: {
    ipAddress: ip,
    ipSlug,
    quotaDate: today,
    quota,
    message,
  },
}];
